<script setup lang="ts">import {computed,reactive,ref} from "vue";import {Play,Check,X,Pencil,ShieldCheck} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import ConfirmDialog from "@/components/zs/ConfirmDialog.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney,parseMoneyInput} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {CopilotAction} from "@/types/operations";setPageMeta("AI Execution Copilot","Interpret commands, review impact and approve controlled company actions.");const c=useCompanyStore(),history=useAsyncData(()=>operationsRepository.copilot(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),command=ref('Record PKR 450,000 revenue received from Descon today'),preview=ref<CopilotAction|null>(null),confirm=ref(false),editing=ref(false),fields=reactive<Record<string,string>>({});function interpret(){const q=command.value.toLowerCase();const intent:CopilotAction['intent']=q.includes('employee')?'add_employee':q.includes('invoice')?'create_invoice':'record_revenue';const amount=parseMoneyInput(command.value.match(/[\d,]+(?:\.\d{1,2})?/)?.[0]??'0')??0;const f:Record<string,string>=intent==='add_employee'?{name:'New employee',email:'',department:'Engineering',start_date:'2026-09-29'}:intent==='create_invoice'?{customer:'Descon Engineering',due_date:'2026-10-22',description:'Professional services'}:{customer:'Descon Engineering',date:'2026-09-22',bank_account:'Habib Metro ••0142',revenue_account:'Software Services Revenue'};Object.assign(fields,f);preview.value={id:'preview',company_id:c.activeCompanyId,command:command.value,intent,summary:intent==='add_employee'?'Create an employee draft':intent==='create_invoice'?'Create a customer invoice':'Record received revenue with a balanced journal',status:'preview',amount:intent==='add_employee'?undefined:amount,warnings:intent==='add_employee'?['Employee invite and payroll access require separate approval.']:amount>10000000?['High-value transaction requires Finance Administrator approval.']:[],fields:{...f},created_at:new Date().toISOString()};editing.value=false}async function approve(){if(!preview.value)return;const saved=await operationsRepository.addCopilot(c.activeCompanyId,{command:preview.value.command,intent:preview.value.intent,summary:preview.value.summary,status:'executed',amount:preview.value.amount,warnings:preview.value.warnings,fields:{...fields}});preview.value={...saved};confirm.value=false;showToast('Action executed in preview','Production execution will be revalidated and written to the audit log.');await history.refresh()}function reject(){if(preview.value)preview.value.status='rejected';showToast('Action rejected','No company records were changed.','info')}</script><template><AppShell><PageHeader title="AI Execution Copilot" description="Describe an action, verify the interpretation, then explicitly approve execution"><template #actions><span class="zs-badge badge-warning">Frontend preview</span></template></PageHeader><div class="grid gap-4 xl:grid-cols-[1fr_25rem]"><Panel title="Command workspace" description="Supports revenue, invoices and employee drafts in this stage"><form class="border-b border-line p-4" @submit.prevent="interpret"><textarea v-model="command" class="field min-h-24 w-full" aria-label="Copilot command"></textarea><div class="mt-3 flex justify-end"><ZButton type="submit"><Play class="size-4"/>Interpret command</ZButton></div></form><div v-if="preview" class="space-y-5 p-5"><div class="flex items-start justify-between gap-3"><div><p class="label-caps">Proposed action</p><h2 class="mt-1 text-lg font-semibold text-content">{{preview.summary}}</h2></div><StatusBadge :status="preview.status"/></div><div v-if="preview.warnings.length" class="rounded-md bg-warning-subtle p-3 text-xs text-warning-strong"><p v-for="w in preview.warnings" :key="w">{{w}}</p></div><div class="grid gap-3 sm:grid-cols-2"><label v-for="(_,key) in fields" :key="key"><span class="label-caps">{{String(key).replaceAll('_',' ')}}</span><input v-model="fields[key]" class="field mt-1.5 w-full" :disabled="!editing"/></label></div><div v-if="preview.amount" class="rounded-md bg-surface-sunken p-4"><p class="label-caps">Accounting impact</p><div class="mt-3 flex justify-between text-sm"><span>Debit Bank</span><span class="num">{{formatMoney(preview.amount)}}</span></div><div class="mt-2 flex justify-between text-sm"><span>Credit Revenue</span><span class="num">{{formatMoney(preview.amount)}}</span></div><p class="mt-3 text-xs text-content-muted">Balanced · Open period · Account mapping present</p></div><div v-if="preview.status==='preview'" class="flex flex-wrap gap-2"><ZButton @click="confirm=true"><Check class="size-4"/>Approve</ZButton><ZButton variant="outline" @click="editing=!editing"><Pencil class="size-4"/>{{editing?'Finish editing':'Edit'}}</ZButton><ZButton variant="ghost" @click="reject"><X class="size-4"/>Reject</ZButton></div></div><div v-else class="p-10 text-center text-sm text-content-muted">Enter a command to generate a permission-aware action preview.</div></Panel><div class="space-y-4"><Panel title="Safety checks"><ul class="space-y-3 p-4 text-xs text-content-secondary"><li class="flex gap-2"><ShieldCheck class="size-4 text-success"/>Active company scope confirmed</li><li class="flex gap-2"><ShieldCheck class="size-4 text-success"/>Required fields validated</li><li class="flex gap-2"><ShieldCheck class="size-4 text-success"/>Explicit approval required</li><li class="flex gap-2"><ShieldCheck class="size-4 text-success"/>Audit record prepared</li></ul></Panel><Panel title="Recent executions"><div v-if="history.data.value?.length" class="divide-y divide-line"><div v-for="x in history.data.value" :key="x.id" class="p-3"><p class="text-xs font-medium text-content">{{x.summary}}</p><p class="mt-1 text-2xs text-content-muted">{{new Date(x.created_at).toLocaleString('en-GB')}}</p></div></div><p v-else class="p-5 text-xs text-content-muted">No approved actions yet.</p></Panel></div></div><ConfirmDialog :open="confirm" title="Approve and execute?" message="The active company, permissions and financial period will be checked again by the future backend." confirm-label="Approve execution" @cancel="confirm=false" @confirm="approve"/></AppShell></template>